// Repo-owned, code-reviewed store knowledge. This module is the ONLY source the
// assistant may use for shipping, returns, payment methods, promotions, tax
// display and market facts (docs/adr/0004-chat-assistant-guardrails.md).
//
// Facts are answered verbatim and are never generated by the LLM or fetched
// from the web. `not_published` facts deliberately answer with an explicit
// "I don't know": the store has not published those policies yet. When a policy
// is decided (e.g. blocking open question #5 for shipping cost), edit this
// module and its tests only.

export type VerifiedFactStatus = "verified" | "not_published";

export interface VerifiedFact {
  /** Stable identifier used by tests and by the answer composition. */
  id: string;
  /** Keyword phrases that route a shopper message to this fact. */
  topics: readonly string[];
  status: VerifiedFactStatus;
  /** Exact shopper-facing English answer; answered verbatim. */
  answer: string;
  /** Durable document that justifies the fact. */
  source: string;
}

