/** Lowercases and separates words, so keyword phrases match regardless of punctuation. */
function normalize(message: string): string {
  return message
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .trim()
    .replace(/\s+/g, " ");
}

function phrasePattern(phrase: string): RegExp {
  const words = phrase
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .trim()
    .split(/\s+/)
    .filter(Boolean)
    .map((word) => word.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"));
  return new RegExp(`\\b${words.join("\\s+")}\\b`);
}

/**
 * Returns every fact whose topic phrases appear in the shopper message.
 * Matching is deterministic and conservative: no embeddings or fuzzy matching.
 */
export function findFactsFor(
  message: string,
  knowledge: readonly VerifiedFact[] = STORE_KNOWLEDGE,
): VerifiedFact[] {
  const text = normalize(message);
  if (text === "") return [];

  const matched = new Map<string, VerifiedFact>();
  for (const fact of knowledge) {
    if (fact.topics.some((topic) => phrasePattern(topic).test(text))) {
      matched.set(fact.id, fact);
    }
  }
  // "Do you ship free?" contains the generic market phrase "do you ship", but it
  // asks about shipping cost. When the shipping-cost unknown also matches, it
  // wins: a market statement never answers a rate question.
  if (matched.has("shipping-cost")) matched.delete("market");
  // "offer" is also a generic verb ("Do you offer free shipping?"). Keep the
  // promotions unknown only when the shopper actually names a promotion.
  if (matched.has("shipping-cost") && matched.has("promotions")) {
    if (!/\b(promo|promotion|promotions|discount|discounts|coupon|coupons|sale)\b/.test(text)) {
      matched.delete("promotions");
    }
  }
  return [...matched.values()];
}
